  1→package agent
  2→
  3→import "time"
  4→
  5→// AgentSession represents a coding session's data.
  6→// Each agent stores data in its native format (JSONL, SQLite, Markdown, etc.)
  7→// and only the originating agent can read/write it.
  8→//
  9→// Design: Sessions are NOT interoperable between agents. A session created by
 10→// Claude Code can only be read/written by Claude Code. This simplifies the
 11→// implementation as we don't need format conversion.
 12→//
 13→//nolint:revive // AgentSession is clearer than Session in context of the package
 14→type AgentSession struct {
 15→	SessionID  string
 16→	AgentName  AgentName
 17→	RepoPath   string
 18→	SessionRef string // Path/reference to session in agent's storage
 19→	StartTime  time.Time
 20→
 21→	// NativeData holds the session content in the agent's native format.
 22→	// Only the originating agent can interpret this data.
 23→	// Examples:
 24→	//   - Claude Code: raw JSONL bytes
 25→	//   - Cursor: serialized SQLite rows
 26→	//   - Aider: Markdown content
 27→	NativeData []byte
 28→
 29→	// Computed fields - populated by the agent when reading
 30→	ModifiedFiles []string
 31→	NewFiles      []string
 32→	DeletedFiles  []string
 33→
 34→	// Optional normalized entries - agents may populate this if needed
 35→	// for operations that benefit from structured access
 36→	Entries []SessionEntry
 37→}
 38→
 39→// SessionEntry represents a single entry in the session
 40→type SessionEntry struct {
 41→	UUID      string
 42→	Type      EntryType
 43→	Timestamp time.Time
 44→	Content   string
 45→
 46→	// Tool-specific fields
 47→	ToolName      string
 48→	ToolInput     interface{}
 49→	ToolOutput    interface{}
 50→	FilesAffected []string
 51→}
 52→
 53→// EntryType categorizes session entries
 54→type EntryType string
 55→
 56→const (
 57→	EntryUser      EntryType = "user"
 58→	EntryAssistant EntryType = "assistant"
 59→	EntryTool      EntryType = "tool"
 60→	EntrySystem    EntryType = "system"
 61→)
 62→
 63→// GetLastUserPrompt returns the last user message content
 64→func (s *AgentSession) GetLastUserPrompt() string {
 65→	for i := len(s.Entries) - 1; i >= 0; i-- {
 66→		if s.Entries[i].Type == EntryUser {
 67→			return s.Entries[i].Content
 68→		}
 69→	}
 70→	return ""
 71→}
 72→
 73→// GetLastAssistantResponse returns the last assistant message content
 74→func (s *AgentSession) GetLastAssistantResponse() string {
 75→	for i := len(s.Entries) - 1; i >= 0; i-- {
 76→		if s.Entries[i].Type == EntryAssistant {
 77→			return s.Entries[i].Content
 78→		}
 79→	}
 80→	return ""
 81→}
 82→
 83→// TruncateAtUUID returns a new session truncated at the given UUID (inclusive)
 84→func (s *AgentSession) TruncateAtUUID(uuid string) *AgentSession {
 85→	if uuid == "" {
 86→		return s
 87→	}
 88→
 89→	truncated := &AgentSession{
 90→		SessionID:  s.SessionID,
 91→		AgentName:  s.AgentName,
 92→		RepoPath:   s.RepoPath,
 93→		SessionRef: s.SessionRef,
 94→		StartTime:  s.StartTime,
 95→	}
 96→
 97→	for i, entry := range s.Entries {
 98→		truncated.Entries = append(truncated.Entries, entry)
 99→		if entry.UUID == uuid {
100→			truncated.Entries = s.Entries[:i+1]
101→			break
102→		}
103→	}
104→
105→	// Recompute file lists from truncated entries
106→	fileSet := make(map[string]bool)
107→	for _, entry := range truncated.Entries {
108→		for _, f := range entry.FilesAffected {
109→			if !fileSet[f] {
110→				fileSet[f] = true
111→				truncated.ModifiedFiles = append(truncated.ModifiedFiles, f)
112→			}
113→		}
114→	}
115→
116→	return truncated
117→}
118→
119→// FindToolResultUUID finds the UUID of the entry containing the tool result
120→// for the given tool use ID. Returns the UUID and true if found.
121→func (s *AgentSession) FindToolResultUUID(toolUseID string) (string, bool) {
122→	for _, entry := range s.Entries {
123→		if entry.Type == EntryTool && entry.UUID == toolUseID {
124→			return entry.UUID, true
125→		}
126→	}
127→	return "", false
128→}
129→

  1→package agent
  2→
  3→import (
  4→	"context"
  5→	"encoding/json"
  6→	"fmt"
  7→	"sort"
  8→	"strings"
  9→)
 10→
 11→const (
 12→	// MaxChunkSize is the maximum size for a single transcript chunk.
 13→	// GitHub has a 100MB limit per blob, so we use 50MB to be safe.
 14→	MaxChunkSize = 50 * 1024 * 1024 // 50MB
 15→
 16→	// ChunkSuffix is the format for chunk file suffixes (e.g., ".001", ".002")
 17→	ChunkSuffix = ".%03d"
 18→)
 19→
 20→// ChunkTranscript splits a transcript into chunks using the appropriate agent.
 21→// If agentType is empty or the agent is not found, falls back to JSONL (line-based) chunking.
 22→func ChunkTranscript(ctx context.Context, content []byte, agentType AgentType) ([][]byte, error) {
 23→	if len(content) <= MaxChunkSize {
 24→		return [][]byte{content}, nil
 25→	}
 26→
 27→	// Try to get the agent by type and use its format-aware chunking
 28→	if agentType != "" {
 29→		ag, err := GetByAgentType(agentType)
 30→		if err == nil {
 31→			chunks, chunkErr := ag.ChunkTranscript(ctx, content, MaxChunkSize)
 32→			if chunkErr != nil {
 33→				return nil, fmt.Errorf("agent chunking failed: %w", chunkErr)
 34→			}
 35→			return chunks, nil
 36→		}
 37→	}
 38→
 39→	// Fall back to JSONL chunking (default)
 40→	return ChunkJSONL(content, MaxChunkSize)
 41→}
 42→
 43→// ReassembleTranscript combines chunks back into a single transcript.
 44→// If agentType is empty or the agent is not found, falls back to JSONL (line-based) reassembly.
 45→func ReassembleTranscript(chunks [][]byte, agentType AgentType) ([]byte, error) {
 46→	if len(chunks) == 0 {
 47→		return nil, nil
 48→	}
 49→	if len(chunks) == 1 {
 50→		return chunks[0], nil
 51→	}
 52→
 53→	// Try to get the agent by type and use its format-aware reassembly
 54→	if agentType != "" {
 55→		ag, err := GetByAgentType(agentType)
 56→		if err == nil {
 57→			result, reassembleErr := ag.ReassembleTranscript(chunks)
 58→			if reassembleErr != nil {
 59→				return nil, fmt.Errorf("agent reassembly failed: %w", reassembleErr)
 60→			}
 61→			return result, nil
 62→		}
 63→	}
 64→
 65→	// Fall back to JSONL reassembly (default)
 66→	return ReassembleJSONL(chunks), nil
 67→}
 68→
 69→// ChunkJSONL splits JSONL content at line boundaries.
 70→// This is the default chunking for agents using JSONL format (like Claude Code).
 71→func ChunkJSONL(content []byte, maxSize int) ([][]byte, error) {
 72→	// Handle empty content
 73→	if len(content) == 0 {
 74→		return [][]byte{}, nil
 75→	}
 76→
 77→	lines := strings.Split(string(content), "\n")
 78→	var chunks [][]byte
 79→	var currentChunk strings.Builder
 80→
 81→	for i, line := range lines {
 82→		// Check if adding this line would exceed the chunk size
 83→		lineWithNewline := line + "\n"
 84→
 85→		// Check if a single line exceeds maxSize - this is an error since we can't split JSONL lines
 86→		if len(lineWithNewline) > maxSize {
 87→			return nil, fmt.Errorf("JSONL line %d exceeds maximum chunk size (%d bytes > %d bytes); cannot split a single JSON object", i+1, len(lineWithNewline), maxSize)
 88→		}
 89→
 90→		if currentChunk.Len()+len(lineWithNewline) > maxSize && currentChunk.Len() > 0 {
 91→			// Save current chunk and start a new one
 92→			chunks = append(chunks, []byte(strings.TrimSuffix(currentChunk.String(), "\n")))
 93→			currentChunk.Reset()
 94→		}
 95→		currentChunk.WriteString(lineWithNewline)
 96→	}
 97→
 98→	// Add the last chunk if it has content
 99→	if currentChunk.Len() > 0 {
100→		chunks = append(chunks, []byte(strings.TrimSuffix(currentChunk.String(), "\n")))
101→	}
102→
103→	return chunks, nil
104→}
105→
106→// ReassembleJSONL concatenates JSONL chunks with newlines.
107→func ReassembleJSONL(chunks [][]byte) []byte {
108→	var result strings.Builder
109→	for i, chunk := range chunks {
110→		result.Write(chunk)
111→		if i < len(chunks)-1 {
112→			result.WriteString("\n")
113→		}
114→	}
115→	return []byte(result.String())
116→}
117→
118→// ChunkFileName returns the filename for a chunk at the given index.
119→// Index 0 returns the base filename, index 1+ returns with chunk suffix.
120→func ChunkFileName(baseName string, index int) string {
121→	if index == 0 {
122→		return baseName
123→	}
124→	return baseName + fmt.Sprintf(ChunkSuffix, index)
125→}
126→
127→// ParseChunkIndex extracts the chunk index from a filename.
128→// Returns 0 for the base file (no suffix), or the chunk number for suffixed files.
129→// Returns -1 if the filename doesn't match the expected pattern.
130→func ParseChunkIndex(filename, baseName string) int {
131→	if filename == baseName {
132→		return 0
133→	}
134→
135→	if !strings.HasPrefix(filename, baseName+".") {
136→		return -1
137→	}
138→
139→	suffix := strings.TrimPrefix(filename, baseName+".")
140→	var index int
141→	if _, err := fmt.Sscanf(suffix, "%03d", &index); err != nil {
142→		return -1
143→	}
144→	return index
145→}
146→
147→// SortChunkFiles sorts chunk filenames in order (base file first, then numbered chunks).
148→func SortChunkFiles(files []string, baseName string) []string {
149→	sorted := make([]string, len(files))
150→	copy(sorted, files)
151→
152→	sort.Slice(sorted, func(i, j int) bool {
153→		idxI := ParseChunkIndex(sorted[i], baseName)
154→		idxJ := ParseChunkIndex(sorted[j], baseName)
155→		return idxI < idxJ
156→	})
157→
158→	return sorted
159→}
160→
161→// geminiTranscriptDetect is used for detecting Gemini JSON format.
162→type geminiTranscriptDetect struct {
163→	Messages []interface{} `json:"messages"`
164→}
165→
166→// DetectAgentTypeFromContent detects the agent type from transcript content.
167→// Returns AgentTypeGemini if it appears to be Gemini JSON format, empty AgentType otherwise.
168→// This is used when the agent type is unknown but we need to chunk/reassemble correctly.
169→func DetectAgentTypeFromContent(content []byte) AgentType {
170→	// Quick check: Gemini JSON starts with { and has a messages array
171→	trimmed := strings.TrimSpace(string(content))
172→	if !strings.HasPrefix(trimmed, "{") {
173→		return ""
174→	}
175→
176→	// Try to parse as Gemini JSON format (object with messages array)
177→	var transcript geminiTranscriptDetect
178→	if err := json.Unmarshal(content, &transcript); err != nil {
179→		return ""
180→	}
181→
182→	// Must have at least one message to be considered Gemini format
183→	if len(transcript.Messages) > 0 {
184→		return AgentTypeGemini
185→	}
186→
187→	return ""
188→}
189→

  1→// Package cursor implements the Agent interface for Cursor.
  2→package cursor
  3→
  4→import (
  5→	"context"
  6→	"errors"
  7→	"fmt"
  8→	"os"
  9→	"path/filepath"
 10→	"regexp"
 11→	"time"
 12→
 13→	"github.com/entireio/cli/cmd/entire/cli/agent"
 14→	"github.com/entireio/cli/cmd/entire/cli/paths"
 15→)
 16→
 17→//nolint:gochecknoinits // Agent self-registration is the intended pattern
 18→func init() {
 19→	agent.Register(agent.AgentNameCursor, NewCursorAgent)
 20→}
 21→
 22→// CursorAgent implements the Agent interface for Cursor.
 23→//
 24→//nolint:revive // CursorAgent is clearer than Agent in this context
 25→type CursorAgent struct{}
 26→
 27→// NewCursorAgent creates a new Cursor agent instance.
 28→func NewCursorAgent() agent.Agent {
 29→	return &CursorAgent{}
 30→}
 31→
 32→// Name returns the agent registry key.
 33→func (c *CursorAgent) Name() agent.AgentName {
 34→	return agent.AgentNameCursor
 35→}
 36→
 37→// Type returns the agent type identifier.
 38→func (c *CursorAgent) Type() agent.AgentType {
 39→	return agent.AgentTypeCursor
 40→}
 41→
 42→// Description returns a human-readable description.
 43→func (c *CursorAgent) Description() string {
 44→	return "Cursor - AI-powered code editor"
 45→}
 46→
 47→func (c *CursorAgent) IsPreview() bool { return true }
 48→
 49→// DetectPresence checks if Cursor is configured in the repository.
 50→func (c *CursorAgent) DetectPresence(ctx context.Context) (bool, error) {
 51→	worktreeRoot, err := paths.WorktreeRoot(ctx)
 52→	if err != nil {
 53→		worktreeRoot = "."
 54→	}
 55→
 56→	cursorDir := filepath.Join(worktreeRoot, ".cursor")
 57→	if _, err := os.Stat(cursorDir); err == nil {
 58→		return true, nil
 59→	}
 60→	return false, nil
 61→}
 62→
 63→// GetSessionID extracts the session ID from hook input.
 64→func (c *CursorAgent) GetSessionID(input *agent.HookInput) string {
 65→	return input.SessionID
 66→}
 67→
 68→// ResolveSessionFile returns the path to a Cursor session file.
 69→// Cursor uses JSONL format like Claude Code.
 70→func (c *CursorAgent) ResolveSessionFile(sessionDir, agentSessionID string) string {
 71→	return filepath.Join(sessionDir, agentSessionID+".jsonl")
 72→}
 73→
 74→// ProtectedDirs returns directories that Cursor uses for config/state.
 75→func (c *CursorAgent) ProtectedDirs() []string { return []string{".cursor"} }
 76→
 77→// GetSessionDir returns the directory where Cursor stores session transcripts.
 78→func (c *CursorAgent) GetSessionDir(repoPath string) (string, error) {
 79→	if override := os.Getenv("ENTIRE_TEST_CURSOR_PROJECT_DIR"); override != "" {
 80→		return override, nil
 81→	}
 82→
 83→	homeDir, err := os.UserHomeDir()
 84→	if err != nil {
 85→		return "", fmt.Errorf("failed to get home directory: %w", err)
 86→	}
 87→
 88→	projectDir := sanitizePathForCursor(repoPath)
 89→	return filepath.Join(homeDir, ".cursor", "projects", projectDir), nil
 90→}
 91→
 92→// ReadSession reads a session from Cursor's storage (JSONL transcript file).
 93→// Note: ModifiedFiles is left empty because Cursor's transcript format does not
 94→// contain tool_use blocks. File detection relies on git status instead.
 95→func (c *CursorAgent) ReadSession(input *agent.HookInput) (*agent.AgentSession, error) {
 96→	if input.SessionRef == "" {
 97→		return nil, errors.New("session reference (transcript path) is required")
 98→	}
 99→
100→	data, err := os.ReadFile(input.SessionRef)
101→	if err != nil {
102→		return nil, fmt.Errorf("failed to read transcript: %w", err)
103→	}
104→
105→	return &agent.AgentSession{
106→		SessionID:  input.SessionID,
107→		AgentName:  c.Name(),
108→		SessionRef: input.SessionRef,
109→		StartTime:  time.Now(),
110→		NativeData: data,
111→	}, nil
112→}
113→
114→// WriteSession writes a session to Cursor's storage (JSONL transcript file).
115→func (c *CursorAgent) WriteSession(_ context.Context, session *agent.AgentSession) error {
116→	if session == nil {
117→		return errors.New("session is nil")
118→	}
119→
120→	if session.AgentName != "" && session.AgentName != c.Name() {
121→		return fmt.Errorf("session belongs to agent %q, not %q", session.AgentName, c.Name())
122→	}
123→
124→	if session.SessionRef == "" {
125→		return errors.New("session reference (transcript path) is required")
126→	}
127→
128→	if len(session.NativeData) == 0 {
129→		return errors.New("session has no native data to write")
130→	}
131→
132→	if err := os.WriteFile(session.SessionRef, session.NativeData, 0o600); err != nil {
133→		return fmt.Errorf("failed to write transcript: %w", err)
134→	}
135→
136→	return nil
137→}
138→
139→// FormatResumeCommand returns an instruction to resume a Cursor session.
140→// Cursor is a GUI IDE, so there's no CLI command to resume a session directly.
141→func (c *CursorAgent) FormatResumeCommand(_ string) string {
142→	return "Open this project in Cursor to continue the session."
143→}
144→
145→// sanitizePathForCursor converts a path to Cursor's project directory format.
146→var nonAlphanumericRegex = regexp.MustCompile(`[^a-zA-Z0-9]`)
147→
148→func sanitizePathForCursor(path string) string {
149→	return nonAlphanumericRegex.ReplaceAllString(path, "-")
150→}
151→
152→// ChunkTranscript splits a JSONL transcript at line boundaries.
153→func (c *CursorAgent) ChunkTranscript(_ context.Context, content []byte, maxSize int) ([][]byte, error) {
154→	chunks, err := agent.ChunkJSONL(content, maxSize)
155→	if err != nil {
156→		return nil, fmt.Errorf("failed to chunk JSONL transcript: %w", err)
157→	}
158→	return chunks, nil
159→}
160→
161→// ReassembleTranscript concatenates JSONL chunks with newlines.
162→func (c *CursorAgent) ReassembleTranscript(chunks [][]byte) ([]byte, error) {
163→	return agent.ReassembleJSONL(chunks), nil
164→}
165→

  1→package cursor
  2→
  3→import (
  4→	"context"
  5→	"encoding/json"
  6→	"fmt"
  7→	"os"
  8→	"path/filepath"
  9→	"strings"
 10→
 11→	"github.com/entireio/cli/cmd/entire/cli/agent"
 12→	"github.com/entireio/cli/cmd/entire/cli/jsonutil"
 13→	"github.com/entireio/cli/cmd/entire/cli/paths"
 14→)
 15→
 16→// Ensure CursorAgent implements HookSupport
 17→var (
 18→	_ agent.HookSupport = (*CursorAgent)(nil)
 19→)
 20→
 21→// Cursor hook names - these become subcommands under `entire hooks cursor`
 22→const (
 23→	HookNameSessionStart       = "session-start"
 24→	HookNameSessionEnd         = "session-end"
 25→	HookNameBeforeSubmitPrompt = "before-submit-prompt"
 26→	HookNameStop               = "stop"
 27→	HookNamePreCompact         = "pre-compact"
 28→	HookNameSubagentStart      = "subagent-start"
 29→	HookNameSubagentStop       = "subagent-stop"
 30→)
 31→
 32→// HooksFileName is the hooks file used by Cursor.
 33→const HooksFileName = "hooks.json"
 34→
 35→// entireHookPrefixes are command prefixes that identify Entire hooks
 36→var entireHookPrefixes = []string{
 37→	"entire ",
 38→	"go run ${CURSOR_PROJECT_DIR}/cmd/entire/main.go ",
 39→}
 40→
 41→// HookNames returns the hook verbs Cursor supports.
 42→// These become subcommands: entire hooks cursor <verb>
 43→func (c *CursorAgent) HookNames() []string {
 44→	return []string{
 45→		HookNameSessionStart,
 46→		HookNameSessionEnd,
 47→		HookNameBeforeSubmitPrompt,
 48→		HookNameStop,
 49→		HookNamePreCompact,
 50→		HookNameSubagentStart,
 51→		HookNameSubagentStop,
 52→	}
 53→}
 54→
 55→// InstallHooks installs Cursor hooks in .cursor/hooks.json.
 56→// If force is true, removes existing Entire hooks before installing.
 57→// Returns the number of hooks installed.
 58→// Unknown top-level fields and hook types are preserved on round-trip.
 59→func (c *CursorAgent) InstallHooks(ctx context.Context, localDev bool, force bool) (int, error) {
 60→	worktreeRoot, err := paths.WorktreeRoot(ctx)
 61→	if err != nil {
 62→		worktreeRoot = "."
 63→	}
 64→
 65→	hooksPath := filepath.Join(worktreeRoot, ".cursor", HooksFileName)
 66→
 67→	// Use raw maps to preserve unknown fields on round-trip
 68→	var rawFile map[string]json.RawMessage
 69→	var rawHooks map[string]json.RawMessage
 70→
 71→	existingData, readErr := os.ReadFile(hooksPath) //nolint:gosec // path is constructed from repo root + fixed path
 72→	if readErr == nil {
 73→		if err := json.Unmarshal(existingData, &rawFile); err != nil {
 74→			return 0, fmt.Errorf("failed to parse existing "+HooksFileName+": %w", err)
 75→		}
 76→		if hooksRaw, ok := rawFile["hooks"]; ok {
 77→			if err := json.Unmarshal(hooksRaw, &rawHooks); err != nil {
 78→				return 0, fmt.Errorf("failed to parse hooks in "+HooksFileName+": %w", err)
 79→			}
 80→		}
 81→		if _, ok := rawFile["version"]; !ok {
 82→			rawFile["version"] = json.RawMessage(`1`)
 83→		}
 84→	} else {
 85→		rawFile = map[string]json.RawMessage{
 86→			"version": json.RawMessage(`1`),
 87→		}
 88→	}
 89→
 90→	if rawHooks == nil {
 91→		rawHooks = make(map[string]json.RawMessage)
 92→	}
 93→
 94→	// Parse only the hook types we manage
 95→	var sessionStart, sessionEnd, beforeSubmitPrompt, stop, preCompact, subagentStart, subagentStop []CursorHookEntry
 96→	parseCursorHookType(rawHooks, "sessionStart", &sessionStart)
 97→	parseCursorHookType(rawHooks, "sessionEnd", &sessionEnd)
 98→	parseCursorHookType(rawHooks, "beforeSubmitPrompt", &beforeSubmitPrompt)
 99→	parseCursorHookType(rawHooks, "stop", &stop)
100→	parseCursorHookType(rawHooks, "preCompact", &preCompact)
101→	parseCursorHookType(rawHooks, "subagentStart", &subagentStart)
102→	parseCursorHookType(rawHooks, "subagentStop", &subagentStop)
103→
104→	// If force is true, remove all existing Entire hooks first
105→	if force {
106→		sessionStart = removeEntireHooks(sessionStart)
107→		sessionEnd = removeEntireHooks(sessionEnd)
108→		beforeSubmitPrompt = removeEntireHooks(beforeSubmitPrompt)
109→		stop = removeEntireHooks(stop)
110→		preCompact = removeEntireHooks(preCompact)
111→		subagentStart = removeEntireHooks(subagentStart)
112→		subagentStop = removeEntireHooks(subagentStop)
113→	}
114→
115→	// Define hook commands
116→	var cmdPrefix string
117→	if localDev {
118→		cmdPrefix = "go run ${CURSOR_PROJECT_DIR}/cmd/entire/main.go hooks cursor "
119→	} else {
120→		cmdPrefix = "entire hooks cursor "
121→	}
122→
123→	sessionStartCmd := cmdPrefix + HookNameSessionStart
124→	sessionEndCmd := cmdPrefix + HookNameSessionEnd
125→	beforeSubmitPromptCmd := cmdPrefix + HookNameBeforeSubmitPrompt
126→	stopCmd := cmdPrefix + HookNameStop
127→	preCompactCmd := cmdPrefix + HookNamePreCompact
128→	subagentStartCmd := cmdPrefix + HookNameSubagentStart
129→	subagentEndCmd := cmdPrefix + HookNameSubagentStop
130→
131→	count := 0
132→
133→	// Add hooks if they don't exist
134→	if !hookCommandExists(sessionStart, sessionStartCmd) {
135→		sessionStart = append(sessionStart, CursorHookEntry{Command: sessionStartCmd})
136→		count++
137→	}
138→	if !hookCommandExists(sessionEnd, sessionEndCmd) {
139→		sessionEnd = append(sessionEnd, CursorHookEntry{Command: sessionEndCmd})
140→		count++
141→	}
142→	if !hookCommandExists(beforeSubmitPrompt, beforeSubmitPromptCmd) {
143→		beforeSubmitPrompt = append(beforeSubmitPrompt, CursorHookEntry{Command: beforeSubmitPromptCmd})
144→		count++
145→	}
146→	if !hookCommandExists(stop, stopCmd) {
147→		stop = append(stop, CursorHookEntry{Command: stopCmd})
148→		count++
149→	}
150→	if !hookCommandExists(preCompact, preCompactCmd) {
151→		preCompact = append(preCompact, CursorHookEntry{Command: preCompactCmd})
152→		count++
153→	}
154→	if !hookCommandExists(subagentStart, subagentStartCmd) {
155→		subagentStart = append(subagentStart, CursorHookEntry{Command: subagentStartCmd})
156→		count++
157→	}
158→	if !hookCommandExists(subagentStop, subagentEndCmd) {
159→		subagentStop = append(subagentStop, CursorHookEntry{Command: subagentEndCmd})
160→		count++
161→	}
162→
163→	if count == 0 {
164→		return 0, nil
165→	}
166→
167→	// Marshal modified hook types back into rawHooks
168→	marshalCursorHookType(rawHooks, "sessionStart", sessionStart)
169→	marshalCursorHookType(rawHooks, "sessionEnd", sessionEnd)
170→	marshalCursorHookType(rawHooks, "beforeSubmitPrompt", beforeSubmitPrompt)
171→	marshalCursorHookType(rawHooks, "stop", stop)
172→	marshalCursorHookType(rawHooks, "preCompact", preCompact)
173→	marshalCursorHookType(rawHooks, "subagentStart", subagentStart)
174→	marshalCursorHookType(rawHooks, "subagentStop", subagentStop)
175→
176→	// Marshal hooks and update raw file
177→	hooksJSON, err := json.Marshal(rawHooks)
178→	if err != nil {
179→		return 0, fmt.Errorf("failed to marshal hooks: %w", err)
180→	}
181→	rawFile["hooks"] = hooksJSON
182→
183→	// Write to file
184→	if err := os.MkdirAll(filepath.Dir(hooksPath), 0o750); err != nil {
185→		return 0, fmt.Errorf("failed to create .cursor directory: %w", err)
186→	}
187→
188→	output, err := jsonutil.MarshalIndentWithNewline(rawFile, "", "  ")
189→	if err != nil {
190→		return 0, fmt.Errorf("failed to marshal "+HooksFileName+": %w", err)
191→	}
192→
193→	if err := os.WriteFile(hooksPath, output, 0o600); err != nil {
194→		return 0, fmt.Errorf("failed to write "+HooksFileName+": %w", err)
195→	}
196→
197→	return count, nil
198→}
